        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if processed_count < len(tasks):
        return None

    dist = {name: info['duration'] for name, info in task_info.items()}

    topo_order = []
    temp_in_degree = dict(in_degree)
    q = [name for name, deg in temp_in_degree.items() if deg == 0]
    while q:
        u = q.pop(0)
        topo_order.append(u)
